from itertools import product

def partitions(n, top=None):
    if n == 0:
        yield ()
        return
    if top is None or top > n:
        top = n
    for a in range(top, 0, -1):
        for rest in partitions(n-a, a):
            yield (a,) + rest

def inside(mu, q, r):
    return len(mu) <= r and (not mu or mu[0] <= q)

def contains(lam, mu):
    return all((lam[k] if k < len(lam) else 0) <= (mu[k] if k < len(mu) else 0)
               for k in range(max(len(lam), len(mu))))

def horizontal(lam, mu):
    if not contains(lam, mu):
        return False
    for col in range(1, max(lam[0] if lam else 0, mu[0] if mu else 0)+1):
        added = sum(a >= col for a in mu) - sum(a >= col for a in lam)
        if added not in (0, 1):
            return False
    return True

def pieri(lam, k, q, r):
    return {mu for mu in partitions(sum(lam)+k) if inside(mu, q, r) and horizontal(lam, mu)}

def slots(i, j, p, c):
    return {
        'x0': (i,)*j,
        'x1': (i+1,) + (i,)*(j-1),
        'y1': (i,)*j + (1,),
        'gamma': (i+2,) + (i,)*(j-1) if p >= 2 else None,
        'x2': (i+1, i+1) + (i,)*(j-2),
        'z': (i+1,) + (i,)*(j-1) + (1,),
        'y2': (i,)*j + (2,),
        'theta': (i,)*j + (1, 1) if c >= 2 else None,
    }

def nonnull(*xs):
    return {x for x in xs if x is not None}

tuples = identities = boundary = 0
for i, j in product(range(2, 7), repeat=2):
    for p, c in product(range(1, 6), repeat=2):
        if min(p, c) != 1:
            continue
        q, r = i+p, j+c
        s = slots(i, j, p, c)
        checks = (
            (pieri(s['x0'], 1, q, r), nonnull(s['x1'], s['y1'])),
            (pieri(s['x0'], 2, q, r), nonnull(s['gamma'], s['z'], s['y2'])),
            (pieri(s['x1'], 1, q, r), nonnull(s['gamma'], s['x2'], s['z'])),
            (pieri(s['y1'], 1, q, r), nonnull(s['z'], s['y2'], s['theta'])),
        )
        for actual, expected in checks:
            assert actual == expected, (i, j, p, c, actual, expected)
            identities += 1
        if p == c == 1:
            cols = ['x2', 'z', 'y2']
            rows = [[int(s[name] in pieri(lam, k, q, r)) for name in cols]
                    for lam, k in ((s['x0'], 2), (s['x1'], 1), (s['y1'], 1))]
            assert rows == [[0,1,1], [1,1,0], [0,1,1]], rows
            minor = [[rows[a][b] for b in (1,2)] for a in (0,1)]
            determinant = minor[0][0]*minor[1][1] - minor[0][1]*minor[1][0]
            assert minor == [[1,1], [1,0]] and determinant == -1, (minor, determinant)
            boundary += 1
        tuples += 1
print('INPUT_I_J: 2..6')
print('INPUT_P_C: 1..5 with min(p,c)=1')
print('PARAMETER_TUPLES:', tuples)
print('PIERI_IDENTITIES_CHECKED:', identities)
print('DOUBLY_BOUNDARY_MATRIX_CHECKS:', boundary)
print('DOUBLY_BOUNDARY_MATRIX_COLUMNS: [x2,z,y2]')
print('DOUBLY_BOUNDARY_MATRIX: [[0,1,1],[1,1,0],[0,1,1]]')
print('DOUBLY_BOUNDARY_MINOR_ROWS_ONE_BASED: [1,2]')
print('DOUBLY_BOUNDARY_MINOR_COLUMNS: [z,y2]')
print('DOUBLY_BOUNDARY_MINOR: [[1,1],[1,0]]')
print('DOUBLY_BOUNDARY_MINOR_DETERMINANT: -1')
print('RESULT: PASS')
